import java.time.LocalDate;

public class MonthEndShifterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static LocalDate on(String text) {
        return LocalDate.parse(text);
    }

    static Object isEnd(String text) {
        try {
            return MonthEndShifter.isLastDayOfMonth(on(text));
        } catch (Throwable crash) {
            return "isLastDayOfMonth threw " + crash.getClass().getSimpleName();
        }
    }

    static Object plain(String text, int months) {
        try {
            LocalDate result = MonthEndShifter.addMonths(on(text), months);
            return result == null ? "<null>" : result.toString();
        } catch (Throwable crash) {
            return "addMonths threw " + crash.getClass().getSimpleName();
        }
    }

    static Object sticky(String text, int months) {
        try {
            LocalDate result = MonthEndShifter.addMonthsStickyEnd(on(text), months);
            return result == null ? "<null>" : result.toString();
        } catch (Throwable crash) {
            return "addMonthsStickyEnd threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("Feb 29 is a month end in a leap year", true, isEnd("2024-02-29"));
        check("Feb 28 is not a month end in a leap year", false, isEnd("2024-02-28"));
        check("Jan 31 plus a month clamps to Feb 29", "2024-02-29", plain("2024-01-31", 1));
        check("Jan 31 plus a month clamps to Feb 28 in 2023", "2023-02-28", plain("2023-01-31", 1));
        check("sticky end matches plain addition from Jan 31", "2024-02-29", sticky("2024-01-31", 1));
        check("sticky end climbs back to Mar 31", "2024-03-31", sticky("2024-02-29", 1));
        check("a mid-month date is left alone", "2024-03-15", sticky("2024-02-15", 1));
        check("sticky end over thirteen months", "2025-02-28", sticky("2024-01-31", 13));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

