/**
 * TASK: Handle the month-end trap when adding months.
 *
 * isLastDayOfMonth(date) reports whether date is the final day of its month.
 *   2024-02-29 -> true, 2024-02-28 -> false
 *
 * addMonths(date, months) is plain LocalDate.plusMonths. Java clamps a day that
 * does not exist in the target month, so 2024-01-31 plus 1 month is 2024-02-29.
 *
 * addMonthsStickyEnd(date, months) keeps an end-of-month date ON the end of the
 * month. If date is the last day of its month, the result is the last day of
 * the target month; otherwise it behaves exactly like addMonths.
 *   2024-01-31 plus 1 month -> 2024-02-29 (same as addMonths)
 *   2024-02-29 plus 1 month -> 2024-03-31 (addMonths alone would give 2024-03-29)
 *   2024-02-15 plus 1 month -> 2024-03-15 (not a month end, so nothing special)
 *
 * Hint: LocalDate has lengthOfMonth() and withDayOfMonth(int).
 */
import java.time.LocalDate;

public class MonthEndShifter {

    public static boolean isLastDayOfMonth(LocalDate date) {
        return date.getDayOfMonth() == date.lengthOfMonth();
    }

    public static LocalDate addMonths(LocalDate date, int months) {
        return date.plusMonths(months);
    }

    public static LocalDate addMonthsStickyEnd(LocalDate date, int months) {
        LocalDate shifted = date.plusMonths(months);
        if (isLastDayOfMonth(date)) {
            return shifted.withDayOfMonth(shifted.lengthOfMonth());
        }
        return shifted;
    }
}
